<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{actualizarConfiguracion,cambiarEstadoConfiguracion,crearConfiguracion,listarConfiguraciones,type Configuracion,type Pair,type Payload}from'../services/configuraciones'
const rows=ref<Configuracion[]>([]),objects=ref<string[]>([]),attributes=ref<string[]>([]),pairs=ref<Pair[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),modal=ref(false),editing=ref<Configuracion|null>(null),error=ref(''),success=ref('');const filters=reactive({objeto:'',atributo:''}),form=reactive<Payload>({objeto:'',atributo:'',valor:'',descripcion:''}),objectMode=ref<'existing'|'new'>('existing'),attributeMode=ref<'existing'|'new'>('existing');const filterAttributes=computed(()=>filters.objeto?[...new Set(pairs.value.filter(x=>x.objeto===filters.objeto).map(x=>x.atributo))]:attributes.value);const formAttributes=computed(()=>[...new Set(pairs.value.filter(x=>x.objeto===form.objeto).map(x=>x.atributo))]);const groups=computed(()=>{const map=new Map<string,{objeto:string;atributo:string;items:Configuracion[]}>();rows.value.forEach(x=>{const key=`${x.objeto}\0${x.atributo}`;if(!map.has(key))map.set(key,{objeto:x.objeto,atributo:x.atributo,items:[]});map.get(key)!.items.push(x)});return [...map.values()]})
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarConfiguraciones(filters.objeto,filters.atributo,p);rows.value=r.data;objects.value=r.objetos;attributes.value=r.atributos;pairs.value=r.pares;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=msg(e)}finally{loading.value=false}}function objectFilterChanged(){filters.atributo=''}function open(x?:Configuracion){editing.value=x||null;Object.assign(form,x?{objeto:x.objeto,atributo:x.atributo,valor:x.valor,descripcion:x.descripcion}:{objeto:objects.value[0]||'',atributo:'',valor:'',descripcion:''});objectMode.value='existing';attributeMode.value='existing';modal.value=true;error.value=''}function objectChanged(){form.atributo='';attributeMode.value='existing'}async function save(){for(const value of Object.values(form))if(!value.trim()){error.value='Complete todos los campos obligatorios.';return}const duplicate=rows.value.some(x=>x.id!==editing.value?.id&&x.objeto.toLowerCase()===form.objeto.toLowerCase()&&x.atributo.toLowerCase()===form.atributo.toLowerCase()&&x.valor.toLowerCase()===form.valor.toLowerCase());if(duplicate){error.value='Ya existe este valor para el objeto y atributo seleccionados.';return}saving.value=true;try{const data={objeto:form.objeto.trim(),atributo:form.atributo.trim(),valor:form.valor.trim(),descripcion:form.descripcion.trim()};if(editing.value){await actualizarConfiguracion(editing.value.id,data);success.value='Configuración actualizada correctamente.'}else{await crearConfiguracion(data);success.value='Configuración registrada correctamente.'}modal.value=false;await load(editing.value?page.value:1)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function toggle(x:Configuracion){const action=x.estado?'desactivar':'activar';if(!confirm(`¿${action[0]!.toUpperCase()+action.slice(1)} la configuración ${x.valor}?`))return;try{await cambiarEstadoConfiguracion(x.id,!x.estado);success.value=`Configuración ${x.estado?'desactivada':'activada'} correctamente.`;await load(page.value)}catch(e){error.value=msg(e)}}function clear(){Object.assign(filters,{objeto:'',atributo:''});load(1)}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Configuraciones</nav><header class="hero"><div class="mark">⚙</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Configuraciones de Catastro</h1><p>Objetos, atributos y valores maestros para los procesos catastrales.</p></div><div class="counter"><b>{{total}}</b><span>valores configurados</span></div><button @click="open()">+ Nueva configuración</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Objeto<select v-model="filters.objeto" @change="objectFilterChanged"><option value="">Todos los objetos</option><option v-for="x in objects" :key="x" :value="x">{{x}}</option></select></label><label>Atributo<select v-model="filters.atributo"><option value="">Todos los atributos</option><option v-for="x in filterAttributes" :key="x" :value="x">{{x}}</option></select></label><div><button @click="load(1)">Buscar</button><button class="clear" @click="clear">Limpiar</button></div></section><div v-if="loading" class="empty">Cargando configuraciones…</div><div v-else-if="!groups.length" class="empty"><b>Sin configuraciones</b><span>No existen valores con los filtros seleccionados.</span></div><section v-else class="groups"><article v-for="g in groups" :key="`${g.objeto}-${g.atributo}`"><header><div><small>OBJETO</small><h2>{{g.objeto}}</h2><span>{{g.atributo}}</span></div><b>{{g.items.length}}</b></header><div class="table"><div v-for="x in g.items" :key="x.id" :class="{inactive:!x.estado}"><span class="value">{{x.valor}}</span><p>{{x.descripcion}}</p><em>{{x.estado?'Activo':'Inactivo'}}</em><button @click="open(x)">Editar</button><button :class="x.estado?'off':'on'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></div></div></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO VALOR'}}</small><h2>{{editing?'Editar configuración':'Registrar configuración'}}</h2></div><button type="button" @click="modal=false">×</button></header><label>Objeto *<div class="choice"><button type="button" :class="{active:objectMode==='existing'}" @click="objectMode='existing';form.objeto=objects[0]||'';objectChanged()">Existente</button><button type="button" :class="{active:objectMode==='new'}" @click="objectMode='new';form.objeto='';objectChanged()">Nuevo</button></div><select v-if="objectMode==='existing'" v-model="form.objeto" @change="objectChanged"><option value="">Seleccione</option><option v-for="x in objects" :key="x" :value="x">{{x}}</option></select><input v-else v-model.trim="form.objeto" placeholder="Nombre del nuevo objeto"></label><label>Atributo *<div class="choice"><button type="button" :class="{active:attributeMode==='existing'}" :disabled="!formAttributes.length" @click="attributeMode='existing';form.atributo=formAttributes[0]||''">Existente</button><button type="button" :class="{active:attributeMode==='new'}" @click="attributeMode='new';form.atributo=''">Nuevo</button></div><select v-if="attributeMode==='existing'" v-model="form.atributo"><option value="">Seleccione</option><option v-for="x in formAttributes" :key="x" :value="x">{{x}}</option></select><input v-else v-model.trim="form.atributo" placeholder="Nombre del nuevo atributo"></label><label>Valor *<input v-model.trim="form.valor" placeholder="Ej. 1, A, ACTIVO"></label><label>Descripción *<textarea v-model.trim="form.descripcion" rows="3" placeholder="Descripción del valor"></textarea></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#536b79;color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-size:1rem}.hero small,.modal small,.groups small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.counter{margin-left:auto;text-align:right}.counter b,.counter span{display:block}.counter b{font-size:.9rem}.counter span{font-size:.43rem}.hero>button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.49rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr auto;align-items:end;gap:8px;background:#fff}.filters label,.modal label{font-size:.47rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.filters .clear,.modal .clear{margin-left:4px;color:#64737a;background:#edf1f2}.groups{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.groups>article{overflow:hidden;border-radius:8px;background:#fff}.groups>article>header{padding:11px;display:flex;align-items:center;justify-content:space-between;color:#fff;background:var(--a)}.groups h2{margin:2px 0;font-size:.68rem}.groups header small{color:#dce5e9}.groups header span{font-size:.46rem}.groups header>b{padding:5px 8px;border-radius:50%;background:#ffffff2b;font-size:.48rem}.table>div{padding:8px;display:grid;grid-template-columns:.5fr 1.5fr .5fr auto auto;align-items:center;gap:5px;border-bottom:1px solid #e9edee;font-size:.43rem}.table .value{padding:4px;border-radius:4px;col